# Find and print the mismatch locations in more detail
mid = len(grid) // 2
transformed_top = [[2 if x==8 else (3 if x==5 else 7) for x in row] for row in grid[:mid]]
bottom_half = grid[mid:]

mismatches = []
for r in range(len(bottom_half)):
    for c in range(len(bottom_half[0])):
        if transformed_top[r][c] != bottom_half[r][c]:
            mismatches.append((r, c, transformed_top[r][c], bottom_half[r][c]))

print(f"Total mismatches: {len(mismatches)}")
print("\nMismatch details:")
for r, c, expected, actual in mismatches:
    print(f"Row {mid+r}, Col {c}: expected {expected}, got {actual}")

# Hypothesis: overlay the two patterns
mid = len(grid) // 2
top_half = grid[:mid]
bottom_half = grid[mid:]

def make_overlay(g1, g2):
    result = []
    for r in range(len(g2)):
        row = []
        for c in range(len(g2[0])):
            v1 = g1[r][c]
            v2 = g2[r][c]

            # Top map: 8->2, 5->3, 7->transparent
            t_map = {8: 2, 5: 3, 7: None}

            # Bottom values are already mapped (no change needed)
            b_map = {2: 2, 3: 3, 7: None}

            m1 = t_map.get(v1)
            m2 = b_map.get(v2)

            if m1 is None and m2 is None:
                row.append(7)
            elif m1 is None:
                row.append(m2)
            elif m2 is None:
                row.append(m1)
            else:
                # Both have values - bottom takes precedence
                row.append(m2)
        result.append(row)
    return result

overlay = make_overlay(top_half, bottom_half)

# Check against actual
match_count = 0
for r in range(len(overlay)):
    for c in range(len(overlay[0])):
        if overlay[r][c] == grid[r][c]:
            match_count += 1

total_cells = len(grid) * len(grid[0])
print(f"Overlay match: {match_count}/{total_cells} = {match_count/total_cells*100:.1f}%")

# Find mismatches
mismatches = []
for r in range(len(grid)):
    for c in range(len(grid[0])):
        expected = grid[r][c]
        actual = overlay[r][c]
        if expected != actual:
            mismatches.append((r, c, expected, actual))

print(f"\nMismatches: {len(mismatches)}")

# Simple color mapping on entire grid
def simple_transform(g):
    result = []
    for row in g:
        new_row = []
        for cell in row:
            if cell == 8:
                new_row.append(2)
            elif cell == 5:
                new_row.append(3)
            else:
                new_row.append(cell)
        result.append(new_row)
    return result

output = simple_transform(grid)

# Check against original (if this is supposed to be identity on bottom)
match_count = 0
for r in range(len(grid)):
    for c in range(len(grid[0])):
        if output[r][c] == grid[r][c]:
            match_count += 1

print(f"Simple transform self-match: {match_count}/{len(grid)*len(grid[0])} = {match_count/(len(grid)*len(grid[0]))*100:.1f}%")

# Compare transformed top vs bottom
top_trans = output[:mid]
bottom_orig = grid[mid:]

top_matches_bottom = 0
for r in range(len(top_trans)):
    for c in range(len(top_trans[0])):
        if top_trans[r][c] == bottom_orig[r][c]:
            top_matches_bottom += 1

print(f"Transformed top vs original bottom: {top_matches_bottom}/{len(grid)/2 * len(grid[0])} = {top_matches_bottom/(len(grid)/2 * len(grid[0]))*100:.1f}%")

# Check where transformed top matches bottom exactly
mid = len(grid) // 2
top_half = grid[:mid]
bottom_half = grid[mid:]

def transform_color(g):
    result = []
    for row in g:
        new_row = []
        for cell in row:
            if cell == 8:
                new_row.append(2)
            elif cell == 5:
                new_row.append(3)
            else:
                new_row.append(cell)
        result.append(new_row)
    return result

trans_top = transform_color(top_half)
print("Checking trans_top[r][c] == bottom[r][c]:")

matches = []
mismatches_pos = []

for r in range(mid):
    for c in range(len(grid[0])):
        if trans_top[r][c] == bottom_half[r][c]:
            matches.append((r,c))
        else:
            mismatches_pos.append((r,c, trans_top[r][c], bottom_half[r][c]))

print(f"Matches: {len(matches)}, Mismatches: {len(mismatches_pos)}")

# Show first few mismatches
for r, c, t, b in mismatches_pos[:20]:
    print(f"Row {r}, Col {c}: top_trans={t}, bot={b}")

